from pathlib import Path
import base64
import gzip
import subprocess

main_path = Path("app/src/main/java/com/ramsiers/graniteapp/MainActivity.java")
build_path = Path("app/build.gradle")
marker = "private void shareLiveEditorChanges()"
version = "versionName '1.16-test'"

patch_gzip_base64 = ""

main = main_path.read_text()
build = build_path.read_text()
if marker in main and version in build:
    print("v1.16 ChatGPT share button already applied.")
else:
    patch = gzip.decompress(base64.b64decode(patch_gzip_base64))
    result = subprocess.run(
        ["git", "apply", "--whitespace=nowarn", "-"],
        input=patch,
        capture_output=True,
    )
    if result.returncode != 0:
        raise RuntimeError(result.stderr.decode("utf-8", errors="replace"))
    print("Applied v1.16 ChatGPT settings share button.")
